fn bitwise_xor(a: Vec<u8>, b: Vec<u8>) -> Vec<u8> {
    // Create a new vector to hold the results
    let mut result = Vec::with_capacity(a.len());
    
    // Iterate over the indices of the input vectors
    for i in 0..a.len() {
        // Perform the XOR operation and push the result to the output vector
        result.push(a[i] ^ b[i]);
    }
    
    // Return the resulting vector
    result
}